from h import *
L=[]
L.append(R(2966,"Pangsit Anggur","Pernahkah Anda mendengar tentang Pangsit Anggur? Inilah kesempatan Anda mencoba sajian khas North Carolina ini dengan mengikuti resep ramah ginjal dari ahli gizi DaVita, Barb.","6","1/3 cangkir",
["1/2 cangkir tepung terigu serbaguna putih","3/4 sendok teh baking powder","1 sendok teh gula","1/8 sendok teh garam","1/2 sendok makan margarin","1-1/4 cangkir jus anggur","1 cangkir air"],
["Dalam mangkuk sedang, campurkan tepung, baking powder, gula, garam, dan shortening. Tambahkan 1/2 cangkir jus anggur dan aduk hingga menjadi adonan yang kaku.","Giling adonan hingga sangat tipis di atas talenan yang ditaburi tepung, lalu potong menjadi strip selebar 1/2” dan sepanjang 1”.","Campurkan 1 cangkir jus anggur dengan 1 cangkir air dalam panci, lalu panaskan hingga mendidih.","Masukkan potongan adonan ke dalam jus anggur yang mendidih dan masak selama 10 hingga 12 menit.","Sajikan pangsit dengan sedikit kuahnya."],
["Sajikan sebagai hidangan pendamping makanan Anda atau sebagai makanan penutup."],["1/2 karbohidrat","1/2 buah"]))
L.append(R(2971,"Makaroni dan Keju","Makaroni dan keju adalah makanan penghibur yang sempurna. Michele dari North Carolina menciptakan versi rendah fosfor dan rendah natrium ini untuk menyenangkan keluarganya sekaligus tetap ramah ginjal.","4","1/2 cangkir",
["1 cangkir pasta rotini gandum utuh, belum dimasak","6 ons krim keju rendah lemak","2 sendok makan mentega tanpa garam","1/2 cangkir susu rendah lemak","1 siung bawang putih","3 sendok makan keju parmesan parut","1/8 sendok teh serpihan cabai merah tumbuk","1/4 sendok teh lada hitam"],
["Masak pasta sesuai petunjuk pada kemasan, tanpa menambahkan garam.","Dalam panci dengan api kecil, lelehkan mentega. Masukkan bawang putih dan didihkan perlahan selama satu menit. Tambahkan krim keju dan aduk hingga meleleh. Tambahkan 1/2 cangkir susu dan kocok hingga menjadi saus. Tambahkan lebih banyak susu hingga kekentalan yang diinginkan. Didihkan saus perlahan dengan api kecil-sedang, berhati-hatilah agar tidak gosong.","Aduk keju parmesan. Taburkan sedikit serpihan cabai merah, dan lada hitam secukupnya.","Campurkan saus dengan pasta yang sudah dimasak, lalu nikmati!"],
["Sayuran dan daging ayam matang juga dapat ditambahkan sesuai selera agar menjadi hidangan satu piring."],["1-1/2 karbohidrat","1 susu","1-1/2 lemak"]))
L.append(R(2973,"Sorbet Stroberi","Saatnya menyegarkan diri di bulan-bulan yang hangat ini, jadi mengapa tidak menikmatinya dengan cara sehat lewat resep Sorbet Stroberi yang ramah ginjal.","4","1/2 cangkir",
["1 cangkir stroberi beku atau segar","1 sendok makan jus lemon","1/4 cangkir air","1-1/4 cangkir es batu"],
["Masukkan es batu ke dalam blender","Tambahkan semua bahan","Putar kecepatan ke mode menghancurkan atau menghaluskan"],
["Dapat dibuat dalam cetakan es batu atau cetakan Popsicle®.","Tambahkan gula atau pengganti gula untuk rasa manis ekstra."],["1/2 buah, rendah kalium"]))
L.append(R(2974,"Kubis Cranberry","Ahli gizi DaVita, Heather dari Georgia, senang menghabiskan waktu di dapur untuk menciptakan resep lezat yang ramah ginjal bagi pasien-pasiennya. Salah satu favoritnya adalah Kubis Cranberry.","8","1/2 cangkir",
["10 ons saus cranberry utuh kalengan","1 sendok makan jus lemon segar","1/4 sendok teh cengkih bubuk","1 kepala kubis merah ukuran sedang"],
["Dalam panci besar, panaskan saus cranberry, jus lemon, dan cengkih bersama-sama hingga mendidih perlahan.","Masukkan kubis ke dalam saus cranberry yang telah meleleh, aduk rata. Didihkan campuran; kecilkan api hingga mendidih perlahan. Lanjutkan memasak hingga kubis empuk, sesekali diaduk.","Sajikan selagi hangat."],
["Satu kepala kubis ukuran sedang menghasilkan 6 cangkir kubis cincang."],["1 sayuran, rendah kalium","1 tinggi kalori"]))
L.append(R(2976,"Air Infus Apel Kayu Manis","Air putih adalah salah satu minuman paling sehat bagi pasien ginjal, tetapi tidak harus hambar dan tanpa rasa! Cobalah Air Infus Apel-Kayu Manis, salah satu dari banyak resep air infus dari ahli gizi DaVita, Kara.","10","1 cangkir (8 ons)",
["10 cangkir air","1 buah apel ukuran sedang","2 batang kayu manis","2 sendok teh kayu manis bubuk"],
["Potong apel yang tidak dikupas menjadi irisan tipis.","Masukkan semua bahan ke dalam teko.","Dinginkan di lemari es semalaman sebelum disajikan."],
["Jika Anda membatasi cairan, sesuaikan ukuran porsi dengan kebutuhan Anda.","Setelah rasanya meresap, Anda dapat menuangkannya ke dalam cetakan es batu untuk membuat es batu beraroma."],["tidak ada"]))
L.append(R(2977,"Salad Tuna dengan Apel dan Seledri","Matilde, ahli gizi DaVita dari Texas, memahami bahwa makanan melambangkan kenyamanan dan beralih ke pola makan sehat bisa sulit bagi pasien-pasiennya. Itulah sebabnya salah satu keahlian Matilde adalah membagikan resep favorit keluarga yang lezat dan ramah ginjal. Salad tuna dengan apel dan seledri ini gurih, kaya protein, dan mudah dibuat.","4","1/4 mangkuk tuna (sekitar 3/4 cangkir)",
["15 ons tuna kalengan tanpa garam, dalam air","1/2 buah apel besar","1 batang seledri","1/2 bawang bombai kecil","3 sendok makan mayones","1/8 sendok teh lada hitam","1/8 sendok teh garam (opsional)"],
["Tiriskan tuna, lalu cincang halus apel, seledri, dan bawang bombai.","Campurkan tuna, apel, seledri, bawang bombai, mayones, lada hitam, dan garam dalam mangkuk sedang.","Sajikan di atas alas selada, dengan biskuit tanpa garam, atau buat menjadi sandwich."],
["Sesuaikan porsi jika Anda menjalani diet rendah protein. Tanyakan kepada ahli gizi Anda untuk merekomendasikan porsi yang tepat sesuai kebutuhan pribadi Anda.","Sari buah dan sayuran akan menjaga kelembapan salad tuna.","Jika Anda ingin mengunyah sesuatu yang renyah, cobalah Salad Tuna Matilde dengan batang seledri atau buncis yang dikukus sebentar.","Natrium adalah 121 mg per porsi jika garam tidak digunakan."],["4 daging","1/2 sayuran, rendah kalium"]))
L.append(R(2979,"Kue Kering Sarapan Oat Cranberry","Ambil kue kering untuk sarapan, asalkan mengandung bahan-bahan sehat seperti pada Kue Kering Sarapan Oat Cranberry yang ramah ginjal ini. Saus apel, cranberry, oat, dan bubuk protein mengubah kue kering yang kaya rasa ini menjadi pilihan sarapan yang hebat.","12","1 kue kering",
["1/2 cangkir mentega tanpa garam","1/2 cangkir gula pasir","1 butir telur besar","1/4 cangkir tepung terigu serbaguna","1 sendok teh ekstrak vanila","1/2 sendok teh kayu manis","1/4 sendok teh garam","1.5 ons bubuk protein whey rasa vanila","1 cangkir saus apel","3 cangkir oat gulung","1/2 cangkir cranberry kering"],
["Biarkan mentega di luar hingga lunak pada suhu ruang. Panaskan oven terlebih dahulu hingga 350° F. Alasi loyang dengan kertas roti.","Dengan mixer listrik, kocok mentega dan gula hingga lembut dan mengembang. Masukkan telur, tepung, bubuk protein, ekstrak vanila, kayu manis, dan garam. Aduk hingga tercampur.","Masukkan saus apel dan campurkan. Lipat oat dan cranberry ke dalamnya.","Sendokkan adonan kue sebanyak 1/4 cangkir ke atas loyang. Pipihkan setiap kue sedikit.","Panggang selama 12 hingga 15 menit, hingga kue berwarna cokelat keemasan tetapi masih lembut.","Biarkan kue mendingin selama 5 menit di atas loyang sebelum dipindahkan ke rak untuk didinginkan sepenuhnya."],
["Simpan kue kering dalam wadah kedap udara atau bungkus satu per satu dan bekukan hingga siap diambil untuk sarapan cepat saat bepergian.","Ukuran sendok takar bervariasi untuk setiap merek bubuk protein. Periksa label untuk mengetahui berat satu sendok takar guna menentukan jumlah yang ditambahkan, atau gunakan timbangan untuk mengukur 1.5 ons.","Nikmati kue kering sarapan ini sebagai camilan. Pertimbangkan untuk membuat 24 kue yang lebih kecil, bukan 12."],["1/2 daging","1 karbohidrat","1 tinggi kalori","1 lemak"]))
L.append(R(2980,"Steak Flank dengan Marinasi Lobak Pedas","Marinasi ini membantu menjaga steak tetap empuk dan juicy sekaligus memberikan banyak rasa.","4","3 ons",
["1 pon steak flank","1/4 cangkir minyak canola","2 siung bawang putih","2 sendok makan lobak pedas (horseradish) tumbuk utuh","1 sendok makan mustard biji utuh kasar","1/2 sendok teh lada hitam","daun bawang untuk hiasan, opsional"],
["Tusuk steak flank dengan garpu agar steak dapat menyerap rasa marinasi. Taburi kedua sisi dengan sedikit lada.","Geprek dan cincang halus bawang putih. Kocok minyak, bawang putih, horseradish, dan mustard bersama-sama dalam wadah tertutup atau kantong sekali pakai. Lumuri steak dan pijat dengan marinasi. Diamkan di lemari es setidaknya 2-4 jam atau semalaman untuk hasil terbaik.","Panggang steak sekitar 5 menit per sisi hingga tingkat kematangan yang diinginkan dan saat suhu internal mencapai 165 derajat. Angkat steak dari panggangan ke talenan bersih dan diamkan 5-10 menit sebelum disajikan. Sebagai alternatif, Anda dapat menggunakan panci panggang atau wajan di atas kompor."],
["Carilah steak yang sudah dipotong dan tipis. Jika tidak tipis, Anda dapat menutupnya dengan plastik pembungkus dan memukulnya hingga pipih. Ini membantu steak matang lebih cepat dan merata.","Carilah horseradish dan mustard kasar dengan kandungan natrium per porsi paling rendah."],["3 protein","1 lemak"]))
L.append(R(2982,"Sup Ayam Nasi Lemon","Sup ayam dan nasi ini memiliki sentuhan lemon yang memberikan rasa unik pada sup ini.","6","1 cangkir",
["2 sendok makan minyak zaitun","1 bawang bombai besar","1 batang seledri","2 cangkir daging ayam matang","4 siung bawang putih","1 wortel besar","8 cangkir air, dibagi","2 sendok makan saus Worcestershire","2 sendok makan jus lemon","1/2 sendok teh garam","3/4 sendok teh lada","3/4 cangkir beras, belum dimasak"],
["Cincang bawang bombai, seledri, dan ayam. Cincang halus bawang putih dan iris wortel. Panaskan panci 5 liter dengan api sedang. Masukkan minyak zaitun, bawang bombai, seledri, bawang putih, dan wortel. Tumis sekitar 5 menit atau hingga sayuran empuk.","Masukkan ayam dan 4 cangkir air, saus Worcestershire, jus lemon, garam, lada, dan beras. Masak 15 menit dengan api sedang atau hingga nasi matang.","Tambahkan 4 cangkir air terakhir dan lanjutkan memasak hingga panas merata."],
["Mengurangi garam menjadi 1/4 sendok teh akan menurunkan natrium menjadi 211 mg per porsi.","Anda dapat menggunakan beras merah atau putih dalam resep ini. Beras merah mungkin membutuhkan waktu sedikit lebih lama untuk menjadi empuk. Beras merah mengandung kalium dan fosfor yang sedikit lebih banyak, tetapi tidak semua mineral tersebut akan diserap oleh tubuh."],["2 protein","1 karbohidrat","1 sayuran, rendah kalium"]))
L.append(R(2983,"Ayam Calabria","Ayam ini membawa sedikit kehangatan dan rasa manis. Cobalah sebagai pengganti cara Anda biasa memasak ayam.","2","1 dada ayam atau 2 irisan tipis ayam",
["1 buah lemon","1 sendok teh pasta cabai Calabria","1 sendok teh madu","2 dada ayam, tanpa tulang dan tanpa kulit","1/4 sendok teh lada bubuk","2 sendok makan minyak zaitun","2 siung bawang putih","1 sendok makan krim kental"],
["Peras lemon. Dalam mangkuk kecil, campurkan jus lemon, pasta cabai Calabria, dan madu. Aduk hingga rata.","Belah setiap dada ayam menjadi dua sehingga Anda mendapatkan 2 irisan tipis. Bumbui dengan lada pada kedua sisinya.","Panaskan minyak zaitun dalam wajan dengan api sedang. Masukkan ayam ke dalam wajan dan masak selama 4-5 menit di setiap sisi hingga suhu internal mencapai 165 derajat.","Setelah ayam matang, cincang halus bawang putih dan masukkan ke dalam wajan, masak selama 1 menit hingga harum. Tambahkan campuran cabai dan krim kental, lalu masak 1-2 menit lagi.","Tata ayam di piring dan tuangkan sisa saus di atasnya.","Sajikan dengan nasi jika diinginkan dan selamat menikmati! (nasi tidak termasuk dalam nutrisi per porsi)."],
["Pasta cabai Calabria bisa pedas. Jika Anda sensitif terhadap makanan pedas, Anda dapat mengurangi jumlah pasta cabai hingga setengahnya.","Jika tidak menemukan pasta cabai Calabria, dapat diganti dengan cabai Calabria cincang, saus cabai yang lebih kental, atau serpihan cabai merah."],["3-1/2 daging/protein","1 lemak"]))
L.append(R(2984,"Vinaigrette Madu Mustard Balsamik Mudah","Lain kali saat Anda membuat salad, pertimbangkan untuk menyiramnya dengan Vinaigrette Madu Mustard Balsamik Mudah dari Wai Yin. Perpaduan bahan ramah ginjal—cuka balsamik, minyak zaitun, mustard, madu, dan lada hitam—memberikan rasa manis dan pedas yang membuat salad apa pun istimewa.","8","2 sendok makan",
["1/2 cangkir cuka balsamik","1/3 cangkir minyak zaitun","2 sendok makan madu","1 sendok makan mustard giling batu","1/4 sendok teh lada hitam"],
["Masukkan semua bahan ke dalam toples. Tutup dan kocok kuat-kuat, lalu sajikan segera.","Jika dressing disiapkan lebih awal, kocok dengan baik sebelum disajikan."],
["Siramkan di atas sayuran salad, atau taruh dalam piring saji kecil untuk dicolek (untuk mencegah penggunaan dressing berlebihan).","Simpan sisa dressing di lemari es hingga satu minggu.","Bandingkan merek dan pilih mustard dengan natrium terendah."],["2 lemak","1/2 tinggi kalori"]))
L.append(R(2986,"Bola Daging Swedia","Resep Bola Daging Swedia ini dibuat dengan mempertimbangkan diet ginjal. Hidangan lezat ini dapat dibuat dengan natrium yang dikurangi dan juga dapat disiapkan lebih awal.","24 porsi","2 bola daging",
["1/2 cangkir bawang bombai","2 butir telur besar","3 pon daging sapi giling","1 sendok makan minyak canola","1 cangkir oatmeal, belum dimasak","1/2 cangkir kaldu sapi rendah natrium","1 sendok makan dill kering","2 sendok makan thyme kering","1/4 sendok teh pala","1/4 sendok teh allspice","1/4 sendok teh lada hitam","3 sendok makan mentega tanpa garam","3 sendok makan tepung terigu serbaguna putih","2 cangkir kaldu sapi natrium dikurangi","1/3 cangkir air"],
["Panaskan oven terlebih dahulu hingga 375° F.","Cincang bawang bombai. Kocok telur.","Campurkan 11 bahan pertama dalam mangkuk besar dan aduk rata.","Bentuk bulatan 1” dan letakkan di atas loyang.","Panggang selama 10 hingga 15 menit, hingga bola daging matang sempurna.","Untuk membuat saus, lelehkan mentega dalam panci besar.","Tambahkan tepung, kaldu natrium dikurangi, sisa satu sendok makan thyme kering, dan air. Masak dengan api sedang, aduk hingga mengental.","Masukkan bola daging ke dalam saus dan turunkan suhu agar tetap hangat, atau letakkan dalam wadah penghangat tertutup atau slow cooker dengan pengaturan api kecil."],
["Kaldu natrium dikurangi mengandung 450 hingga 500 mg natrium per cangkir. Kaldu rendah natrium mengandung 140 mg natrium atau kurang per cangkir.","Buat bola daging lebih awal dan simpan di lemari es. Saat siap disajikan, panaskan bahan-bahan bersama-sama dan pindahkan ke wadah penghangat."],["1-1/2 daging","1 lemak"]))
L.append(R(2987,"Kue Wortel Rendah Gula","Bagi penderita yang menjalani dialisis, memasak makanan sendiri dan membuat makanan penutup sendiri membantu Anda mengendalikan diet dialisis. Cobalah resep Kue Wortel Rendah Gula ini dan panggang makanan penutup lezat setelah makan malam atau camilan siang hari yang pasti disukai.","20","1 potong 2-1/4\" x 2-1/2\"",
["2 cangkir tepung terigu serbaguna putih","1/2 sendok teh garam","1/2 sendok teh soda kue","1 sendok teh baking powder","2 sendok makan kayu manis","1-1/2 cangkir minyak canola","1 cangkir Splenda® Sugar Blend for Baking","4 butir telur","3 cangkir wortel, diparut","1/2 cangkir mentega tanpa garam","8 ons krim keju","3/4 cangkir Splenda® No Calorie Sweetener, granulated","1 sendok teh vanila"],
["Panaskan oven terlebih dahulu hingga 350o F.","Olesi loyang 9″ x 13″ dengan lemak dan taburi sedikit tepung.","Ayak tepung, garam, soda kue, baking powder, dan kayu manis bersama-sama. Sisihkan.","Campurkan minyak dan Splenda® Sugar Blend for Baking. Masukkan telur satu per satu, aduk setelah setiap telur ditambahkan.","Tambahkan bahan kering secara bertahap. Aduk rata.","Lipat wortel parut ke dalamnya. Tuang ke dalam loyang dan panggang selama 55 hingga 60 menit hingga tusuk gigi yang ditusukkan ke tengah kue keluar bersih.","Untuk membuat icing, campurkan mentega dan krim keju dalam mangkuk pengaduk. Kocok dengan mixer hingga lembut dan mengembang.","Tambahkan pemanis Splenda® granulated secara bertahap sambil mengocok. Tambahkan vanila dan aduk rata.","Oleskan icing pada kue setelah kue benar-benar dingin."],
["Untuk versi rendah lemak, ganti 1/2 cangkir minyak canola dengan 1/2 cangkir saus apel tanpa pemanis; ganti telur dengan 1 cangkir produk telur rendah kolesterol; gunakan krim keju rendah kalori. (250 kalori, 18 gram lemak per porsi).","Jika diinginkan, ganti produk Splenda dengan gula dalam jumlah yang sama.","Splenda tersedia dalam empat bentuk: Splenda® Sugar Blend for Baking (setengah Splenda®, setengah gula), Splenda® Brown sugar Blend (setengah Splenda, setengah gula merah), pemanis granulated Splenda® dan pemanis tabletop Splenda®. Untuk hasil terbaik gunakan dua jenis yang ditentukan dalam resep ini."],["1 karbohidrat","1/2 sayuran, rendah kalium","5 lemak"]))
L.append(R(2989,"Sate Ayam ala Puerto Riko","Ayam yang dipanggang pada tusuk sate dan dibumbui dengan bumbu Adobo serta saus barbekyu jambu biji pasti disukai semua orang di meja makan.","8","1 tusuk",
["2 pon paha ayam tanpa tulang dan tanpa kulit","2 sendok makan Bumbu Adobo (lihat resep di DaVita.com)","1 sendok makan oregano kering","1 sendok makan cuka putih","2 sendok makan minyak zaitun","2 lembar daun salam","1 cangkir Saus BBQ Jambu Biji (lihat resep di DaVita.com)","8 tusuk sate logam atau bambu"],
["Potong dadu paha ayam menjadi potongan seukuran gigitan 2 inci. Jika menggunakan tusuk sate bambu, rendam dalam air selama 1/2 jam agar tidak terbakar.","Campurkan Bumbu Adobo, oregano, cuka, minyak zaitun, dan daun salam, lalu masukkan ke dalam kantong ziplock.","Masukkan ayam ke dalam marinasi. Simpan di lemari es setidaknya setengah jam hingga semalaman.","Panaskan pemanggang dan olesi jeruji dengan minyak saat sudah panas.","Tusukkan ayam pada tusuk sate dan letakkan di atas pemanggang yang panas. Panggang sebentar sekitar 5 menit di setiap sisi.","Olesi pincho dengan Saus Barbekyu Jambu Biji atau saus barbekyu rendah natrium lainnya dan masak sekitar 4 menit lagi."],
["Jaga agar potongan ayam berukuran kurang lebih sama agar matang merata.","Lihat Saus Barbekyu Jambu Biji kami dan resep saus barbekyu rendah natrium lainnya di DaVita.com.","Buat sendiri Bumbu Adobo rendah natrium Anda."],["3 daging"]))
L.append(R(2990,"Semur Daging Pedas","Semur Daging Pedas memiliki cita rasa unik dari cabai merah, bubuk kari, dan selai kacang. Sup ini rendah natrium dan fosfor, namun kaya rasa.","8","1 cangkir semur + 3/4 cangkir nasi",
["1 cangkir bawang bombai","1 buah tomat roma ukuran sedang","3 buah wortel ukuran sedang","1-1/2 sendok makan minyak goreng","1-1/2 pon daging sapi untuk semur yang tanpa lemak","3 ons pasta tomat","2-1/2 cangkir air","3/4 sendok teh cabai merah bubuk","1/4 sendok teh lada hitam","1/2 sendok teh bubuk kari","2 sendok makan selai kacang halus","6 cangkir nasi putih matang"],
["Potong dadu bawang bombai dan tomat. Kupas dan cincang wortel. Potong daging semur menjadi dadu.","Dalam panci besar, panaskan minyak hingga panas. Masukkan daging sapi, masak sambil diaduk dengan api sedang hingga kecokelatan.","Masukkan bawang bombai ke dalam daging dan tumis hingga bening, sekitar 5 hingga 7 menit.","Tambahkan air, pasta tomat, cabai merah dan lada hitam, serta bubuk kari. Tutup panci dan masak dengan api sedang-kecil hingga sayuran empuk, 20 hingga 25 menit.","Tambahkan selai kacang dan aduk hingga tercampur. Tutup dan masak dengan api kecil selama 20 menit lagi.","Sajikan di atas nasi hangat."],
["Sesuaikan cabai merah sesuai selera.","Simpan sisa semur di lemari es atau bekukan."],["2 daging","2 karbohidrat","1-1/2 sayuran, kalium sedang"]))
save(1,L)
